function mlpProbs(M, f) {
	var H = M.b1.length, h = new Array(H), z = [0, 0, 0, 0], i, j;
	for (j = 0; j < H; j++) {
		var a = M.b1[j];
		for (i = 0; i < f.length; i++) a += (f[i] - M.mu[i]) / M.sd[i] * M.W1[i][j];
		h[j] = Math.tanh(a);
	}
	for (var k = 0; k < 4; k++) { z[k] = M.b2[k]; for (j = 0; j < H; j++) z[k] += h[j] * M.W2[j][k]; }
	var mx = Math.max(z[0], z[1], z[2], z[3]), sum = 0;
	for (k = 0; k < 4; k++) { z[k] = Math.exp(z[k] - mx); sum += z[k]; }
	for (k = 0; k < 4; k++) z[k] /= sum;
	return z;   // K, S, G, H
}

// Stage 2: once the tempo is known, re-decide with metrical position and neighbours
// (ghosts sit on 16th offbeats, hats on 8ths, rolls repeat the same sound, ...).
function stage2Features(slices) {
	var lv = slices.map(function (sl) { return sl.feat[23]; });
	var R = ["K", "S", "G", "H"], med = {};
	R.forEach(function (t) {
		var v = slices.filter(function (sl) { return sl.type === t; }).map(function (sl) { return sl.feat[23]; });
		med[t] = v.length ? median(v) : median(lv);
	});
	return slices.map(function (sl, i) {
		var f = sl.probs.slice();
		var pv = i > 0 ? slices[i - 1].probs : [0, 0, 0, 0], nx = i + 1 < slices.length ? slices[i + 1].probs : [0, 0, 0, 0];
		f = f.concat(pv, nx);
		var q = sl.pos * 4, r = Math.round(q), ph = ((r % 4) + 4) % 4, bt = ((Math.floor(r / 4) % 4) + 4) % 4;
		f.push(Math.min(0.5, Math.abs(q - r)));
		for (var k = 0; k < 4; k++) f.push(ph === k ? 1 : 0);
		for (k = 0; k < 4; k++) f.push(bt === k ? 1 : 0);
		f.push(i > 0 ? Math.min(2, sl.pos - slices[i - 1].pos) : 2, i + 1 < slices.length ? Math.min(2, slices[i + 1].pos - sl.pos) : 2);
		f.push(sl.feat[23] - med[sl.type], sl.feat[23] - med.S, sl.feat[23]);
		return f;
	});
}

function classifyStage2(slices) {
	var R = ["K", "S", "G", "H"];
	var f2 = stage2Features(slices);
	slices.forEach(function (sl, i) {
		sl.feat2 = f2[i];
		if (!CLASSIFIER2) return;
		var p = mlpProbs(CLASSIFIER2, f2[i]), b = 0;
		for (var k = 1; k < 4; k++) if (p[k] > p[b]) b = k;
		sl.type = R[b];
		sl.probs = p;
	});
	ensureKickSnare(slices);
}

function ensureKickSnare(slices) {
	var R = ["K", "S", "G", "H"];
	[0, 1].forEach(function (k) {
		if (slices.some(function (sl) { return sl.type === R[k]; })) return;
		var bi = -1, bv = -1;
		slices.forEach(function (sl, i) { if (sl.type !== R[1 - k] && sl.probs[k] > bv) { bv = sl.probs[k]; bi = i; } });
		if (bi >= 0) slices[bi].type = R[k];
	});
}

function classifySlicesML(slices) {
	var R = ["K", "S", "G", "H"];
	slices.forEach(function (sl) {
		var p = mlpProbs(CLASSIFIER, sl.feat);
		sl.probs = p;
		var b = 0;
		for (var k = 1; k < 4; k++) if (p[k] > p[b]) b = k;
		sl.type = R[b];
		sl.energy = Math.pow(10, sl.feat[23] / 2);   // relative level (feature 23 = level vs loudest)
	});
	ensureKickSnare(slices);
}

function classifySlices(x, sr, slices) {
	var N = 2048, w = hann(N), re = new Float64Array(N), im = new Float64Array(N);
	var feats = [], i, k;
	var binHz = sr / N;
	for (i = 0; i < slices.length; i++) {
		var s = slices[i].s, len = Math.min(N, slices[i].e - s, Math.round(0.08 * sr));
		var e = 0;
		for (k = 0; k < N; k++) {
			var v = k < len ? x[s + k] : 0;
			re[k] = v * (k < len ? w[Math.floor(k * N / Math.max(1, len))] : 0); im[k] = 0;
			if (k < len) e += v * v;
		}
		fft(re, im);
		var low = 0, lmid = 0, mid = 0, high = 0, tot = 0, cen = 0;
		for (k = 1; k < N / 2; k++) {
			var p = re[k] * re[k] + im[k] * im[k], hz = k * binHz;
			tot += p; cen += p * hz;
			if (hz < 150) low += p; else if (hz < 400) lmid += p; else if (hz < 4000) mid += p; else high += p;
		}
		tot = tot || 1e-12;
		feats.push({ low: low / tot, lmid: lmid / tot, mid: mid / tot, high: high / tot,
			cen: Math.log(cen / tot + 1), en: Math.sqrt(e / Math.max(1, len)) });
	}
	function z(key) {
		var m = 0, sd = 0;
		feats.forEach(function (f) { m += f[key]; }); m /= feats.length || 1;
		feats.forEach(function (f) { sd += (f[key] - m) * (f[key] - m); }); sd = Math.sqrt(sd / (feats.length || 1)) || 1;
		return feats.map(function (f) { return (f[key] - m) / sd; });
	}
	var zl = z("low"), zlm = z("lmid"), zm = z("mid"), zh = z("high"), zc = z("cen"), ze = z("en");
	var scores = [];
	for (i = 0; i < slices.length; i++) {
		var pos = slices[i].pos, frac = pos - Math.round(pos), beatIdx = ((Math.round(pos) % 4) + 4) % 4;
		var onBeat = Math.abs(frac) < 0.12;
		var sk = 1.2 * zl[i] - 0.6 * zc[i] + 0.3 * ze[i] + (onBeat && (beatIdx === 0 || beatIdx === 2) ? 0.5 : 0);
		var ss = 0.7 * ze[i] + 0.6 * zm[i] + 0.4 * zlm[i] - 0.5 * zl[i] + (onBeat && (beatIdx === 1 || beatIdx === 3) ? 0.7 : 0);
		var sh = 1.0 * zc[i] + 0.5 * zh[i] - 0.9 * ze[i] - 0.4 * zl[i] + (onBeat ? -0.3 : 0.2);
		scores.push({ K: sk, S: ss, H: sh });
		var t = "K";
		if (ss > sk && ss >= sh) t = "S"; else if (sh > sk && sh > ss) t = "H";
		slices[i].type = t;
		slices[i].energy = feats[i].en;
		slices[i].f = feats[i];
	}
	// guarantee at least one kick and one snare
	["K", "S"].forEach(function (role) {
		if (slices.some(function (sl) { return sl.type === role; })) return;
		var bi = -1, bv = -1e9;
		for (var j = 0; j < slices.length; j++) if (scores[j][role] > bv && slices[j].type !== (role === "K" ? "S" : "K")) { bv = scores[j][role]; bi = j; }
		if (bi >= 0) slices[bi].type = role;
	});
	// quiet snares become ghosts
	var sn = slices.filter(function (sl) { return sl.type === "S"; }).map(function (sl) { return sl.energy; });
	var med = median(sn);
	slices.forEach(function (sl) { if (sl.type === "S" && sl.energy < med * 0.5) sl.type = "G"; });
	// hats with real snare body (150-400 Hz) are ghost snares under a ride
	slices.forEach(function (sl) { if (sl.type === "H" && sl.f.lmid > 0.18 && sl.f.lmid > sl.f.high * 0.8) sl.type = "G"; });
}

// ---------------------------------------------------------------------------
// Pattern generation. Returns [{t, dur, pitch, vel}] in beats.

function generatePattern(an, styleIdx, prm, bars, seed) {
	var st = STYLES[styleIdx] || STYLES[0];
	var rng = mulberry32(seed);
	var P = {};
	DIAL_NAMES.forEach(function (k) { P[k] = (prm[k] !== undefined ? prm[k] : st.defaults[k]) / 100; });
	var slices = an.slices;
	var L16 = Math.max(4, Math.round(an.beats * 4));
	var Lbeats = L16 / 4;

	// original 16th grid -> slice index
	var orig = [];
	for (var q = 0; q < L16; q++) orig.push(-1);
	slices.forEach(function (sl, i) {
		var qq = Math.round(sl.pos * 4);
		if (qq >= 0 && qq < L16 && Math.abs(sl.pos * 4 - qq) < 0.35) {
			if (orig[qq] < 0 || sl.energy > slices[orig[qq]].energy) orig[qq] = i;
		}
	});
	var byRole = { K: [], S: [], G: [], H: [] };
	slices.forEach(function (sl, i) { byRole[sl.type].push(i); });
	if (!byRole.G.length) byRole.G = byRole.S.slice();
	if (!byRole.H.length) byRole.H = slices.map(function (_, i) { return i; }).filter(function (i) { return slices[i].type !== "K"; });

	var barPick = {};
	function pick(role) {
		var list = byRole[role];
		if (!list || !list.length) list = byRole.S.length ? byRole.S : [0];
		if (barPick[role] !== undefined && rng() < 0.6) return barPick[role];
		var idx;
		if (role === "K" || role === "S") {
			// favour the loudest few, they carry the character of the break
			var sorted = list.slice().sort(function (a, b) { return slices[b].energy - slices[a].energy; });
			idx = sorted[Math.floor(Math.pow(rng(), 1.8) * sorted.length)];
		} else idx = list[Math.floor(rng() * list.length)];
		barPick[role] = idx;
		return idx;
	}
	function beatScore(srcBeat, dstBeat) {
		// how well an original beat fits the skeleton of the destination beat
		var sc = 0;
		for (var sub = 0; sub < 4; sub++) {
			var oi = orig[(srcBeat * 4 + sub) % L16], step = dstBeat * 4 + sub;
			var role = oi >= 0 ? slices[oi].type : null;
			if (st.K[step] && role === "K") sc += st.K[step];
			if (st.S[step] && role === "S") sc += st.S[step];
			if (!st.K[step] && !st.S[step] && (role === "K" || role === "S")) sc -= 0.3;
		}
		return sc;
	}

	var ev = [];
	var srcBar = 0;
	for (var bar = 0; bar < bars; bar++) {
		barPick = {};
		var phraseEnd = (bar % 4 === 3) || (bars <= 2 && bar === bars - 1);
		var isFill = phraseEnd && rng() < P.fill;
		var barsInSrc = Math.max(1, Math.floor(Lbeats / 4));
		srcBar = rng() < st.barChop * P.chop * 2 ? Math.floor(rng() * barsInSrc) : bar % barsInSrc;
		for (var beat = 0; beat < 4; beat++) {
			var chopP = P.chop * 0.6 * (isFill && beat >= 2 ? 1.6 : 1);
			var srcBeat = (srcBar * 4 + beat) % Lbeats;
			if (rng() < chopP) {
				var bestB = srcBeat, bestS = -1e9;
				for (var tries = 0; tries < 4; tries++) {
					var cb = Math.floor(rng() * Lbeats), cs = beatScore(cb, beat) + rng() * (1.5 - P.strength);
					if (cs > bestS) { bestS = cs; bestB = cb; }
				}
				srcBeat = bestB;
			}
			for (var sub = 0; sub < 4; sub++) {
				var step = beat * 4 + sub;
				var oi = orig[(srcBeat * 4 + sub) % L16];
				var idx = oi, role = oi >= 0 ? slices[oi].type : null;
				var wantK = st.K[step] || 0, wantS = st.S[step] || 0;
				if (wantK && role !== "K" && rng() < wantK * P.strength) { idx = pick("K"); role = "K"; }
				else if (wantS && role !== "S" && rng() < wantS * P.strength) { idx = pick("S"); role = "S"; }
				else if (idx >= 0 && ((role === "K" && !wantK) || (role === "S" && !wantS)) && rng() < P.strength * 0.35) {
					if (rng() < P.density) { idx = pick("H"); role = "H"; } else { idx = -1; role = null; }
				}
				if (idx < 0) {
					var g = st.G[step] || 0;
					var h = st.H[step] !== undefined ? st.H[step] : (step % 2 ? st.H.odd : 0);
					if (rng() < g * P.ghost * 1.2) { idx = pick("G"); role = "G"; }
					else if (rng() < h * P.density * 1.2) { idx = pick("H"); role = "H"; }
				} else if ((role === "H" || role === "G") && rng() > 0.35 + P.density) {
					idx = -1;
				}
				if (idx < 0) continue;
				var vel = { K: 112, S: 115, G: 58, H: 82 }[role] || 100;
				var revW = (step === 14 || step === 15 || step === 3 || step === 11) ? 1.6 : 0.5;
				var rev = idx < 127 - NOTE_REV && role !== "K" && rng() < P.reverse * revW * 0.6;
				ev.push({ t: bar * 4 + step / 4, idx: idx, rev: rev, vel: vel, role: role });
			}
		}
		// rolls (after the whole bar so later beats can't land inside a roll)
		for (beat = 0; beat < 4; beat++) {
			var rp = P.roll * (beat === 3 ? 0.55 : 0.12) * (isFill ? 2 : 1) * (isFill && beat === 2 ? 1.5 : 1);
			if (rng() < rp) {
				var ri = Math.floor(rng() * st.rollRates.length);
				var rate = st.rollRates[ri], rrole = st.rollRoles[ri];
				var rlen = (beat === 3 && rng() < 0.5) || !isFill ? 0.5 : 1;
				var rs = bar * 4 + beat + (rlen === 0.5 ? 0.5 : 0);
				var re_ = rs + rlen;
				ev = ev.filter(function (e) { return e.t < rs - 1e-6 || e.t >= re_ - 1e-6; });
				var rIdx = pick(rrole), cnt = Math.round(rlen / rate);
				for (var r = 0; r < cnt; r++) {
					ev.push({ t: rs + r * rate, idx: rIdx, rev: false, vel: Math.round(60 + 60 * (r + 1) / cnt), role: "R" });
				}
			}
		}
	}
	ev.sort(function (a, b) { return a.t - b.t; });

	// swing on 16th offbeats (0..100 -> up to a 16th triplet)
	ev.forEach(function (e) {
		var s16 = e.t * 4;
		if (Math.abs(s16 - Math.round(s16)) < 1e-6 && Math.round(s16) % 2 === 1) e.t += P.swing * (1 / 12);
	});
	var total = bars * 4, out = [];
	for (var i = 0; i < ev.length; i++) {
		var e = ev[i], next = i + 1 < ev.length ? ev[i + 1].t : total;
		var d = Math.max(1 / 32, Math.min(next - e.t, 1));
		var v = Math.max(1, Math.min(127, Math.round(e.vel + (rng() - 0.5) * 12)));
		out.push({ t: Math.round(e.t * 1e4) / 1e4, dur: Math.round(d * 1e4) / 1e4,
			pitch: e.rev ? NOTE_REV + e.idx : NOTE_BASE + e.idx, vel: v, role: e.role });
	}
	return out;
}

// ---------------------------------------------------------------------------
// Max glue (not used by the offline tests)

var S = {
	style: 0, source: 0, pick: 1, query: "drum break", key: "",
	prm: {}, bars: 2, startbar: 1, seed: 0, playhead: 0,
	pitch: 0, length: 100, choke: 1, sync: 0
};
var bufNames = null, ready = false, pendingState = null;
var state = { path: "", name: "", license: "", bpm: 0, beats: 0, slices: [] };
var logLines = [], reqId = 0, pending = {};

function devicePath() {
	var p = "";
	try { p = jsthis.patcher.filepath || ""; } catch (e) { }
	var i = p.indexOf(":/");
	return i >= 0 ? p.slice(i + 1) : p;
}
function deviceDir() { var p = devicePath(); return /\.(amxd|maxpat)$/i.test(p) ? p.slice(0, p.lastIndexOf("/")) : p; }
function downloadDir() {
	var m = /^\/Users\/[^\/]+/.exec(devicePath());
	return m ? m[0] + "/Music/Ableton/User Library/Samples/BreakGen" : deviceDir();
}

var DEBUG_URL = "";   // e.g. "http://127.0.0.1:8765/log" to stream the log to test/logserver.py
function log(msg) {
	var line = new Date().toISOString() + " " + msg;
	logLines.push(line);
	if (logLines.length > 200) logLines.shift();
	try {
		var f = new File(maxPath(deviceDir() + "/breakgen.log"), "write");
		if (f.isopen) { f.eof = 0; f.writestring(logLines.join("\n") + "\n"); f.close(); }
	} catch (e) { }
	if (DEBUG_URL) {
		var d = new Dict();
		d.set("url", DEBUG_URL); d.set("http_method", "post");
		d.set("post_data", "m=" + encodeURIComponent(line));
		d.set("response_dict", "bg_log");
		outlet(2, "dictionary", d.name);
	}
}
// Max file APIs want "Volume:/path"; keep the volume prefix of the device path
function maxPath(p) {
	var raw = "";
	try { raw = jsthis.patcher.filepath || ""; } catch (e) { }
	var i = raw.indexOf(":/");
	return i > 0 && p.charAt(0) === "/" ? raw.slice(0, i + 1) + p : p;
}
function status(msg) { outlet(3, "set", msg); log("status: " + msg); }

function names(b, s) { bufNames = { brk: b, sl: s }; }
function init() {
	ready = true;
	readKey();
	pushVoiceParams();
	outlet(4, S.choke ? 1 : 0);
	if (pendingState) { applyState(pendingState); pendingState = null; }
	else status("Ready — pick a source and press Fetch, or drop a file.");
	log("init device=" + devicePath() + " raw=" + (function () { try { return jsthis.patcher.filepath; } catch (e) { return "?"; } })() + " dl=" + downloadDir());
}

// ---- UI inputs
function style(v) {
	var i = Math.max(0, Math.min(STYLES.length - 1, v | 0));
	var changed = i !== S.style;
	S.style = i;
	if (changed && ready) {
		var d = STYLES[i].defaults;
		DIAL_NAMES.forEach(function (k) { outlet(5, k, d[k]); });
	}
}
function source(v) { S.source = v | 0; }
function pick(v) { S.pick = Math.max(1, v | 0); }
function query() { S.query = arrayfromargs(arguments).join(" "); saveState(); }
function key() { S.key = arrayfromargs(arguments).join("").trim(); writeKey(); status(S.key ? "Freesound key saved." : "Freesound key cleared."); }
function bars(v) { S.bars = BARS_ENUM[Math.max(0, Math.min(BARS_ENUM.length - 1, v | 0))]; }
function startbar(v) { S.startbar = Math.max(1, v | 0); }
function seed(v) { S.seed = v | 0; }
function playhead(v) { S.playhead = v | 0; }
function pitch(v) { S.pitch = v; pushVoiceParams(); }
function slicelen(v) { S.length = v; pushVoiceParams(); }
function choke(v) { S.choke = v | 0; outlet(4, S.choke ? 1 : 0); }
function sync(v) { S.sync = v | 0; pushVoiceParams(); }
function anything() {
	var k = messagename;
	if (DIAL_NAMES.indexOf(k) >= 0) S.prm[k] = arguments[0];
	else log("unknown message " + k);
}

function pushVoiceParams() {
	var semis = S.pitch;
	if (S.sync && state.bpm > 0) {
		var tempo = songTempo();
		if (tempo > 0) semis += 12 * Math.log(tempo / state.bpm) / Math.LN2;
	}
	outlet(0, "pitch", semis);
	outlet(0, "len", S.length / 100);
}

function songTempo() {
	try { return new LiveAPI("live_set").get("tempo")[0]; } catch (e) { return 0; }
}

// ---- fetching
function fetchsrc(v) {
	if (v !== undefined && !v) return;
	if (!bufNames) { status("Device not initialised yet."); return; }
	if (S.source === 0) fetchClassic();
	else if (S.source === 1) fetchFreesound();
	else fetchUrl(S.query, null);
}

function request(url, opts, cb) {
	var d = new Dict();
	var resp = "bg_resp_" + (++reqId) + "_" + Math.floor(Math.random() * 1e6);
	d.set("url", url);
	d.set("http_method", "get");
	d.set("response_dict", resp);
	d.set("timeout", 60);
	if (opts.file) { d.set("filename_out", opts.file); d.set("overwrite_output_file", 1); }
	if (opts.json) d.set("parse_type", "json");
	if (opts.headers) d.set("headers", opts.headers);
	pending[resp] = cb;
	log("GET " + url + (opts.file ? " -> " + opts.file : ""));
	outlet(2, "dictionary", d.name);
}

function dictionary(name) {
	var cb = pending[name];
	var d = new Dict(name);
	var info = {};
	try {
		d.getkeys().forEach(function (k) { if (k !== "body") info[k] = d.get(k); });
	} catch (e) { }
	if (name === "bg_log") return;
	log("response " + name + " " + JSON.stringify(info).slice(0, 400));
	if (!cb) return;
	delete pending[name];
	var code = info.http_code !== undefined ? info.http_code : info.status;
	var body = null;
	try {
		var b = d.get("body");
		if (b && typeof b === "object" && b.stringify) body = JSON.parse(b.stringify());
		else if (typeof b === "string" && b.length) { try { body = JSON.parse(b); } catch (e) { body = b; } }
	} catch (e) { }
	cb(code, body, info);
}

function fetchClassic() {
	var i = (S.pick - 1) % CLASSIC_FILES.length;
	var base = CLASSIC_FILES[i];
	status("Fetching classic break " + base + " …");
	request("https://archive.org/metadata/" + CLASSIC_ITEM, { json: true }, function (code, meta) {
		var url = "https://archive.org/download/" + CLASSIC_ITEM + "/" + base + ".wav";
		if (meta && meta.d1 && meta.dir) url = "https://" + meta.d1 + meta.dir + "/" + base + ".wav";
		download(url, base + ".wav", {
			name: base, license: "Classic break (Amen) — clear rights before release",
			credit: base + ".wav | archive.org/details/" + CLASSIC_ITEM + " | license: unspecified (classic break sample)"
		});
	});
}

function fetchFreesound() {
	if (!S.key) { status("Enter a Freesound API key first (freesound.org/apiv2/apply)."); return; }
	var q = S.query || "drum break";
	var url = "https://freesound.org/apiv2/search/text/?query=" + encodeURIComponent(q) +
		"&filter=" + encodeURIComponent('duration:[1 TO 30] license:("Creative Commons 0" OR "Attribution")') +
		"&fields=id,name,username,license,duration,previews&page_size=50&token=" + encodeURIComponent(S.key);
	status("Searching Freesound for \"" + q + "\" …");
	request(url, { json: true }, function (code, body) {
		if (!body || !body.results || !body.results.length) { status("Freesound: no results (HTTP " + code + ")."); return; }
		var r = body.results[(S.pick - 1) % body.results.length];
		var prev = r.previews && (r.previews["preview-hq-mp3"] || r.previews["preview_hq_mp3"]);
		if (!prev) { status("Freesound: result has no preview."); return; }
		var lic = /zero/i.test(r.license) ? "CC0" : "CC BY";
		var safe = ("fs" + r.id + "_" + r.name).replace(/[^A-Za-z0-9_\-.]+/g, "_").replace(/\.(wav|aiff?|flac|mp3|ogg)$/i, "");
		download(prev, safe + ".mp3", {
			name: r.name, license: lic + " — " + r.username,
			credit: safe + ".mp3 | \"" + r.name + "\" by " + r.username + " | freesound.org/s/" + r.id + " | " + r.license
		});
	});
}

function fetchUrl(url) {
	if (!/^https?:\/\//.test(url || "")) { status("Type an http(s) URL into the text field."); return; }
	var fname = decodeURIComponent(url.split("?")[0].split("/").pop() || "download").replace(/[^A-Za-z0-9_\-.]+/g, "_");
	if (!/\.(wav|aiff?|mp3|flac|ogg|m4a)$/i.test(fname)) fname += ".wav";
	status("Downloading " + fname + " …");
	var headers = /ccmixter\.org/.test(url) ? ["Referer=http://ccmixter.org/"] : null;
	download(url, fname, { name: fname, license: "URL — check license", credit: fname + " | " + url }, headers);
}

function download(url, fname, meta, headers) {
	var path = downloadDir() + "/" + fname;
	request(url, { file: path, headers: headers }, function (code) {
		if (code && code >= 400) { status("Download failed (HTTP " + code + ")."); return; }
		appendCredit(meta.credit);
		loadFile(path, meta.name, meta.license);
	});
}

function appendCredit(line) {
	try {
		var p = downloadDir() + "/CREDITS.txt";
		var f = new File(maxPath(p), "readwrite");
		if (!f.isopen) return;
		var txt = f.eof > 0 ? f.readstring(f.eof) : "";
		if (txt.indexOf(line) < 0) { f.position = f.eof; f.writestring(line + "\n"); }
		f.close();
	} catch (e) { }
}

function drop(path) {
	var p = String(path);
	if (p.indexOf("/") < 0) return;   // live.drop sends "none" when cleared
	var i = p.indexOf(":/");
	if (i >= 0) p = p.slice(i + 1);
	loadFile(p, p.split("/").pop(), "local file");
}

var loadingMeta = null;
function loadFile(path, name, license) {
	loadingMeta = { path: path, name: name, license: license, analyse: true };
	status("Loading " + name + " …");
	outlet(1, "replace", path);
}

// buffer~ finished reading
function loaded() {
	if (!loadingMeta) return;
	var meta = loadingMeta;
	loadingMeta = null;
	if (!meta.analyse) { writeSliceBuffer(); status(summary()); return; }
	try {
		var b = new Buffer(bufNames.brk);
		var n = b.framecount(), ch = b.channelcount();
		if (!n) { status("Could not read " + meta.name); return; }
		var sr = n / (b.length() / 1000);
		n = Math.min(n, Math.round(sr * 60));
		var x = new Float32Array(n), CH = 65536;
		var nch = Math.min(ch, 2);
		for (var c = 1; c <= nch; c++) {
			for (var off = 0; off < n; off += CH) {
				var cnt = Math.min(CH, n - off), a = b.peek(c, off, cnt);
				if (typeof a === "number") a = [a];
				for (var i = 0; i < cnt; i++) x[off + i] += a[i] / nch;
			}
		}
		outlet(0, "mono", ch < 2 ? 1 : 0);
		var an = analyzeSignal(x, sr, bpmHintFromName(meta.name));
		state = { path: meta.path, name: meta.name, license: meta.license, bpm: an.bpm, beats: an.beats,
			mono: ch < 2 ? 1 : 0,
			slices: an.slices.map(function (sl) {
				return { s: +sl.s.toFixed(2), e: +sl.e.toFixed(2), pos: +sl.pos.toFixed(4), type: sl.type, energy: +sl.energy.toFixed(4) };
			}) };
		writeSliceBuffer();
		pushVoiceParams();
		saveState();
		status(summary());
		log("analysis " + JSON.stringify({ bpm: an.bpm, beats: an.beats, n: an.slices.length,
			types: an.slices.map(function (s) { return s.type; }).join("") }));
	} catch (e) {
		status("Analysis error: " + e);
	}
}

function summary() {
	var c = { K: 0, S: 0, G: 0, H: 0 };
	state.slices.forEach(function (s) { c[s.type]++; });
	return state.name + " | " + state.bpm.toFixed(1) + " BPM, " + state.beats + " beats, " + state.slices.length +
		" slices (K" + c.K + " S" + c.S + " G" + c.G + " H" + c.H + ") | " + state.license;
}

function writeSliceBuffer() {
	var b = new Buffer(bufNames.sl);
	var n = b.framecount();
	var st = [], en = [];
	for (var i = 0; i < n; i++) { st.push(0); en.push(0); }
	state.slices.forEach(function (s, i) {
		if (i < MAX_SLICES) { st[i] = s.s; en[i] = s.e; }
	});
	// reversed notes 84.. read the same rows (the voice subtracts 48)
	b.poke(1, 0, st);
	b.poke(2, 0, en);
	outlet(0, "mono", state.mono ? 1 : 0);
}

// ---- generation
function generate(v) {
	if (v !== undefined && !v) return;
	if (!state.slices.length) { status("Load a break first."); return; }
	var sd = S.seed > 0 ? S.seed : Math.floor(Math.random() * 1e9);
	var notes = generatePattern(state, S.style, S.prm, S.bars, sd);
	try {
		var track = new LiveAPI("this_device canonical_parent");
		if (track.type !== "Track") { status("Put BreakGen directly on a MIDI track (not inside a rack)."); return; }
		var start = (S.startbar - 1) * 4;
		if (S.playhead) {
			var t = new LiveAPI("live_set").get("current_song_time")[0];
			start = Math.floor(t / 4) * 4;
		}
		var len = S.bars * 4;
		var res = track.call("create_midi_clip", start, len);
		var clip = clipFromResult(res, track, start);
		if (!clip) { status("Could not create the clip (is the arrangement free at that position?)."); return; }
		clip.set("name", "Break " + STYLES[S.style].name + " #" + sd);
		writeNotes(clip, notes);
		status("Wrote " + notes.length + " notes, " + S.bars + " bars at bar " + (start / 4 + 1) +
			" (" + STYLES[S.style].name + ", seed " + sd + ").");
		log("pattern " + JSON.stringify(notes.slice(0, 64)));
		if (DEBUG_URL) { diag(); audition(36); }
	} catch (e) {
		status("Generate error: " + e);
	}
}

function clipFromResult(res, track, start) {
	var id = null;
	if (res && res.length >= 2 && res[0] === "id") id = res[1];
	else if (res && res.length === 1 && typeof res[0] === "number") id = res[0];
	if (id !== null && id > 0) return new LiveAPI("id " + id);
	var ids = track.get("arrangement_clips");
	for (var i = 0; i + 1 < ids.length; i += 2) {
		var c = new LiveAPI("id " + ids[i + 1]);
		if (Math.abs(c.get("start_time")[0] - start) < 1e-3) return c;
	}
	return null;
}

function writeNotes(clip, notes) {
	var list = notes.map(function (n) {
		return { pitch: n.pitch, start_time: n.t, duration: n.dur, velocity: n.vel };
	});
	try {
		clip.call("add_new_notes", { notes: list });
	} catch (e) {
		clip.call("set_notes");
		clip.call("notes", list.length);
		list.forEach(function (n) { clip.call("note", n.pitch, n.start_time, n.duration, n.velocity, 0); });
		clip.call("done");
	}
}

function tempo(v) {
	if (v !== undefined && !v) return;
	var bpm = STYLES[S.style].bpm;
	new LiveAPI("live_set").set("tempo", bpm);
	pushVoiceParams();
	status("Tempo set to " + bpm + " BPM (" + STYLES[S.style].name + ").");
}

// ---- persistence (pattr blob) and Freesound key file
function saveState() {
	outlet(7, "set", JSON.stringify({ v: 1, st: state, q: S.query }));
}
function restore(s) {
	var obj;
	try { obj = JSON.parse(String(s)); } catch (e) { return; }
	if (!ready) { pendingState = obj; return; }
	applyState(obj);
}
function applyState(obj) {
	if (!obj || !obj.st) return;
	state = obj.st;
	if (obj.q) { S.query = obj.q; outlet(6, "query", "set", S.query); }
	if (state.path) {
		loadingMeta = { path: state.path, name: state.name, license: state.license, analyse: false };
		outlet(1, "replace", state.path);
	}
	pushVoiceParams();
}
function readKey() {
	try {
		var f = new File(maxPath(deviceDir() + "/freesound_key.txt"), "read");
		if (f.isopen) { S.key = (f.readline() || "").trim(); f.close(); }
		if (S.key) outlet(6, "key", "set", "••••••••");
	} catch (e) { }
}
function writeKey() {
	try {
		var f = new File(maxPath(deviceDir() + "/freesound_key.txt"), "write");
		if (f.isopen) { f.eof = 0; f.writestring(S.key); f.close(); }
	} catch (e) { }
}

// ---- diagnostics
function diag() {
	try {
		var info = [];
		jsthis.patcher.apply(function (b) {
			if (b.maxclass === "poly~" || (b.maxclass === "newobj" && /^poly~/.test(b.boxtext || ""))) {
				var sp = null;
				try { sp = b.subpatcher(0); } catch (e) { }
				var cnt = 0, cls = [];
				if (sp) sp.apply(function (x) { cnt++; if (cls.length < 60) cls.push(x.maxclass); });
				info.push("poly~ voice boxes=" + cnt + " [" + cls.join(",") + "]");
			}
			return true;
		});
		log("diag " + info.join(" | "));
		var b = new Buffer(bufNames.sl);
		log("diag slices frames=" + b.framecount() + " ch=" + b.channelcount() + " row0=" + b.peek(1, 0, 3) + " / " + b.peek(2, 0, 3));
		var bb = new Buffer(bufNames.brk);
		log("diag break frames=" + bb.framecount() + " ch=" + bb.channelcount());
		var track = new LiveAPI("this_device canonical_parent");
		var ids = track.get("arrangement_clips");
		for (var i = 0; i + 1 < ids.length; i += 2) {
			var c = new LiveAPI("id " + ids[i + 1]);
			var js = c.call("get_all_notes_extended");
			log("diag clip " + c.get("name") + " notes=" + String(js).slice(0, 300));
		}
	} catch (e) { log("diag error " + e); }
}
var lastLvl = 0;
function lvl(v) {
	if (!DEBUG_URL) return;
	if ((v > 0.0005) !== (lastLvl > 0.0005)) log("level " + v.toFixed(4));
	lastLvl = v;
}
function audition(p) { outlet(0, "note", p || 36, 110); log("audition " + (p || 36)); }
